// A stand-in for PostCSS: a plugin is an object with `postcssPlugin` and a `fake(css, { messages, options })` function that rewrites the text.
const postcss = (plugins) => ({
  async process(css, options) {
    const messages = [];
    for (const plugin of plugins) css = (await plugin.fake(css, { messages, options })) ?? css;
    return { css, messages, warnings: () => [] };
  },
});
module.exports = postcss;
module.exports.default = postcss;
